"use client";

import Link from "next/link";
import { ArrowLeft, Wifi, Copy, Check } from "lucide-react";
import { useState } from "react";

export default function CidrFormatPage() {
  const [copied, setCopied] = useState(false);

  const cidrExample = `192.168.1.0/24
10.0.0.0/16
2001:db8::/32`;

  const copyToClipboard = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error("Failed to copy:", error);
    }
  };

  return (
    <div className="space-y-6">
      <Link
        href="/docs"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to Documentation
      </Link>

      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono font-bold text-[#22e57a] tracking-widest uppercase bg-[rgba(34,229,122,.08)] px-3 py-1 rounded-md border border-[rgba(34,229,122,.1)]">
            Data Format
          </span>
        </div>
        <h1 className="text-3xl md:text-4xl font-bold font-mono text-[#f2fff8]">
          CIDR Notation
        </h1>
        <p className="text-[#93a79d] font-mono text-lg max-w-2xl">
          Each record is stored as a CIDR network range, which makes filtering,
          validation, and routing logic easier.
        </p>
      </div>

      <div className="bg-[rgba(34,229,122,.03)] border border-[rgba(34,229,122,.08)] rounded-xl p-6">
        <div className="flex items-center gap-2 mb-3">
          <Wifi size={16} className="text-[#22e57a]" />
          <h2 className="text-lg font-mono font-bold text-[#f2fff8]">
            Example
          </h2>
        </div>
        <div className="relative">
          <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-4 overflow-x-auto font-mono text-sm text-[#7fe9ab]">
            {cidrExample}
          </pre>
          <button
            onClick={() => copyToClipboard(cidrExample)}
            className="absolute top-3 right-3 p-1.5 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
          >
            {copied ? (
              <Check size={14} className="text-[#22e57a]" />
            ) : (
              <Copy size={14} className="text-[#6f8a7d]" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
}
